220: func parseEvents(raw []byte) (text string, tokens Tokens, cost float64, sessionID string, toolCalls, eventCount int) {
221: 	scanner := bufio.NewScanner(bytes.NewReader(raw))
222: 	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
223: 	var builder strings.Builder
224: 	for scanner.Scan() {
225: 		line := bytes.TrimSpace(scanner.Bytes())
226: 		if len(line) == 0 {
227: 			continue
228: 		}
229: 		var item event
230: 		if err := json.Unmarshal(line, &item); err != nil {
231: 			continue
232: 		}
233: 		eventCount++
234: 		if item.SessionID != "" {
235: 			sessionID = item.SessionID
236: 		}
237: 		var part map[string]json.RawMessage
238: 		if err := json.Unmarshal(item.Part, &part); err != nil {
239: 			continue
240: 		}
241: 		if typeRaw, ok := part["type"]; ok {
242: 			var partType string
243: 			_ = json.Unmarshal(typeRaw, &partType)
244: 			if strings.HasPrefix(partType, "tool") {
245: 				toolCalls++
246: 			}
247: 		}
248: 		if item.Type == "text" {
249: 			if textRaw, ok := part["text"]; ok {
250: 				var chunk string
251: 				if json.Unmarshal(textRaw, &chunk) == nil {
252: 					builder.WriteString(chunk)
253: 				}
254: 			}
255: 		}
256: 		if item.Type == "step_finish" {
257: 			var finish finishPart
258: 			if json.Unmarshal(item.Part, &finish) == nil {
259: 				cost = finish.Cost
260: 				tokens.Input = finish.Tokens.Input
261: 				tokens.Output = finish.Tokens.Output
262: 				tokens.Reasoning = finish.Tokens.Reasoning
263: 				tokens.CacheRead = finish.Tokens.Cache.Read
264: 				tokens.CacheWrite = finish.Tokens.Cache.Write
265: 			}
266: 		}
267: 	}
268: 	return builder.String(), tokens, cost, sessionID, toolCalls, eventCount
269: }
