271: // VerifyTask runs the task verification command inside the isolated workspace.
272: func VerifyTask(record *RunRecord, task Task, timeout time.Duration) error {
273: 	if task.VerifyCommand == "" || record.WorkDir == "" {
274: 		return nil
275: 	}
276: 	if timeout <= 0 {
277: 		timeout = 2 * time.Minute
278: 	}
279: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
280: 	defer cancel()
281: 	parts := strings.Fields(task.VerifyCommand)
282: 	if len(parts) == 0 {
283: 		return nil
284: 	}
285: 	cmd := exec.CommandContext(ctx, parts[0], parts[1:]...)
286: 	cmd.Dir = record.WorkDir
287: 	output, err := cmd.CombinedOutput()
288: 	record.VerifyOutput = string(output)
289: 	if exitError, ok := err.(*exec.ExitError); ok {
290: 		record.VerifyExitCode = exitError.ExitCode()
291: 	} else if err != nil {
292: 		record.VerifyExitCode = -1
293: 	}
294: 	record.VerifyPassed = err == nil
295: 	return nil
296: }
