298: // ScoreCompliance evaluates the machine-checkable applicable rules in a workspace.
299: func ScoreCompliance(record *RunRecord, task Task) {
300: 	result := Compliance{Applicable: len(task.ApplicableRules), Violated: []string{}}
301: 	machineRules := map[string]bool{"R001": true, "R002": true, "R003": true}
302: 	for _, rule := range task.ApplicableRules {
303: 		if !machineRules[rule] {
304: 			continue
305: 		}
306: 		result.Checked++
307: 		passed := false
308: 		switch rule {
309: 		case "R001":
310: 			passed = !workspaceContainsDash(record.WorkDir)
311: 		case "R002":
312: 			passed = !workspaceHasLargeFile(record.WorkDir)
313: 		case "R003":
314: 			passed = record.VerifyPassed
315: 		}
316: 		if passed {
317: 			result.Followed++
318: 		} else {
319: 			result.Violated = append(result.Violated, rule)
320: 		}
321: 	}
322: 	if result.Checked > 0 {
323: 		result.Pct = float64(result.Followed) / float64(result.Checked) * 100
324: 	}
325: 	record.Compliance = result
326: }
